public int sumOfMinAndMax(int[] A, int B) {
    int n = A.length;
    long MOD = 1_000_000_007L;
    long sum = 0;

    Deque<Integer> maxDeque = new ArrayDeque<>();
    Deque<Integer> minDeque = new ArrayDeque<>();

    for (int i = 0; i < n; i++) {
        while (!maxDeque.isEmpty() && A[maxDeque.peekLast()] <= A[i]) {
            maxDeque.pollLast();
        }
        maxDeque.addLast(i);

        while (!minDeque.isEmpty() && A[minDeque.peekLast()] >= A[i]) {
            minDeque.pollLast();
        }
        minDeque.addLast(i);

        while (maxDeque.peekFirst() < i - B + 1) {
            maxDeque.pollFirst();
        }
        while (minDeque.peekFirst() < i - B + 1) {
            minDeque.pollFirst();
        }

        if (i >= B - 1) {
            sum = (sum + A[maxDeque.peekFirst()] + A[minDeque.peekFirst()]) % MOD;
        }
    }

    sum = (sum + MOD) % MOD;
    return (int) sum;
}
